// Auftrag lesen (Stefan 18.10.2026): Eingang von Oberfläche (bericht_id schon angelegt), Chat (Einzelfelder) oder Zeitplan (auftrag als JSON).
// Ergebnis für "Bericht anlegen": bericht_id ('' = neu anlegen), nutzer, auftrag (JSON-Text), quelle, vorlage_id.
const e = $input.first().json || {};
const s = v => String(v ?? '').trim();
const id = /^[0-9]{1,12}$/.test(s(e.bericht_id)) ? s(e.bericht_id) : '';
let auftrag = {};
if (e.auftrag && typeof e.auftrag === 'object') auftrag = e.auftrag;
else if (s(e.auftrag).startsWith('{')) { try { auftrag = JSON.parse(s(e.auftrag)); } catch (x) { auftrag = {}; } }
// Einzelfelder (Chat-Werkzeug) ergänzen, wenn kein vollständiger Auftrag übergeben wurde
for (const k of ['art', 'talents', 'talent_namen', 'kanal', 'zeitraum', 'monat', 'von', 'bis', 'bausteine', 'mit_agentur', 'kampagne_id', 'titel']) {
  if (auftrag[k] === undefined && s(e[k]) !== '') auftrag[k] = s(e[k]);
}
const quelle = ['oberflaeche', 'chat', 'plan'].includes(s(e.quelle)) ? s(e.quelle) : 'chat';
return [{ json: { bericht_id: id, nutzer: s(e.nutzer), auftrag: JSON.stringify(auftrag), quelle, vorlage_id: /^[0-9]{1,9}$/.test(s(e.vorlage_id)) ? s(e.vorlage_id) : '' } }];

