-- Bericht anlegen (Stefan 18.10.2026, Vertrag Migration 47): von der Oberfläche schon angelegt (bericht_id), sonst neu (Chat, Zeitplan).
SELECT CASE WHEN nullif($1::text, '') IS NOT NULL THEN jsonb_build_object('ok', true, 'bericht_id', nullif($1::text, '')::bigint)
            ELSE talents_bericht_start($2::text, $3::jsonb, $4::text, nullif($5::text, '')::integer) END AS s;

