// KI-Eingabe bauen (Stefan 18.10.2026): nur gespeicherte Zahlen als knappes JSON (keine Links, keine Bilder, keine Namen von Personen der Agentur).
// Die KI schreibt eine kurze Einordnung; sie rechnet nicht und erfindet nichts. Fehlt ein Wert, steht er als "nicht verfügbar" in den Daten.
const R = $('Inhalt laden').first().json.r || {};
const B = R.bericht || {};
const L = Array.isArray;
const t = w => (w && typeof w === 'object' ? (w.wert === null || w.wert === undefined ? 'nicht verfügbar' : String(w.text)) : (w === null || w === undefined || w === '' ? 'nicht verfügbar' : String(w)));
const ver = w => (w && w.veraenderung && w.veraenderung.text && w.veraenderung.text !== '–' ? w.veraenderung.text : 'nicht verfügbar');
const daten = { bericht: B.art_name, zeitraum: B.zeitraum_text, kanaele: B.kanal_text, bausteine: {} };
for (const b of (L(R.bausteine) ? R.bausteine : [])) {
  const je = L(b.je_talent) ? b.je_talent : null;
  const proTalent = f => je ? je.map(x => Object.assign({ talent: x.anzeigename }, f(x.daten || {}))) : [];
  if (b.schluessel === 'kennzahlen') daten.bausteine.kennzahlen = proTalent(d => ({
    kennzahlen: (L(d.kennzahlen) ? d.kennzahlen : []).map(k => ({ name: k.name, wert: t(k), veraenderung_zum_vorzeitraum: k.schluessel === 'follower' ? undefined : ver(k),
      zuwachs: k.schluessel === 'follower' ? t(k.zuwachs) : undefined, manuell: k.manuell === true ? (k.quelle_text || 'manuell') : undefined })),
    hinweise: d.hinweise }));
  else if (b.schluessel === 'beitraege' || b.schluessel === 'beispiele') daten.bausteine[b.schluessel] = proTalent(d => ({
    anzahl_im_zeitraum: d.anzahl_im_zeitraum,
    beitraege: (L(d.beitraege) ? d.beitraege : []).map(p => ({ art: p.art_name, datum: p.erstellt, reichweite: t(p.reichweite), aufrufe: t(p.aufrufe), interaktionen: t(p.interaktionen),
      interaktionsrate: p.interaktionsrate ? p.interaktionsrate.text : 'nicht verfügbar' })) }));
  else if (b.schluessel === 'zielgruppe') daten.bausteine.zielgruppe = proTalent(d => ({
    gruppen: (L(d.gruppen) ? d.gruppen : []).map(g => ({ name: g.name, stand: g.stand, top: (L(g.eintraege) ? g.eintraege : []).slice(0, 5).map(e => e.name + ' ' + (e.anteil_text || e.text)) })),
    hinweis: d.hinweis }));
  else if (b.schluessel === 'formate') daten.bausteine.was_funktioniert = proTalent(d => ({
    formate: (L(d.formate) ? d.formate : []).map(f => ({ art: f.name, anzahl: f.anzahl, schnitt_reichweite: t(f.schnitt_reichweite), schnitt_aufrufe: t(f.schnitt_aufrufe),
      schnitt_interaktionen: t(f.schnitt_interaktionen), interaktionsrate: f.interaktionsrate ? f.interaktionsrate.text : 'nicht verfügbar' })) }));
  else if (b.schluessel === 'manuell') daten.bausteine.zahlen_ohne_verbindung = proTalent(d => ({
    werte: (L(d.werte) ? d.werte : []).map(w => ({ kennzahl: w.kennzahl_name, wert: w.text, zeitraum: w.zeitraum_text, quelle: w.quelle_text })) }));
  else if (b.schluessel === 'profil') daten.bausteine.profil = proTalent(d => ({
    follower: t(d.follower), reichweite_28_tage: t(d.reichweite), aufrufe_28_tage: t(d.aufrufe), interaktionen_28_tage: t(d.interaktionen),
    interaktionsrate: d.interaktionsrate ? d.interaktionsrate.text : 'nicht verfügbar', beitraege_28_tage: d.beitraege }));
  else if (b.schluessel === 'vergleich') daten.bausteine.vergleich = (L((b.daten || {}).zeilen) ? b.daten.zeilen : []).map(z => ({
    talent: z.anzeigename, follower: t(z.follower), reichweite: t(z.reichweite), veraenderung_reichweite: ver(z.reichweite), aufrufe: t(z.aufrufe),
    interaktionen: t(z.interaktionen), interaktionsrate: z.interaktionsrate ? z.interaktionsrate.text : 'nicht verfügbar', beitraege: z.beitraege }));
  else if (b.schluessel === 'kampagne') {
    const d = b.daten || {};
    daten.bausteine.kampagne = { name: (d.kampagne || {}).name, marke: (d.kampagne || {}).marke, zeitraum: (d.kampagne || {}).zeitraum_text,
      gesamt: Object.fromEntries(Object.entries(d.gesamt || {}).map(([k, v]) => [k, t(v)])),
      talents: (L(d.talents) ? d.talents : []).map(x => ({ talent: x.anzeigename, reichweite: t(x.reichweite), aufrufe: t(x.aufrufe), interaktionen: t(x.interaktionen),
        beitraege: L(x.beitraege) ? x.beitraege.length : t(x.beitraege) })) };
  }
}
if (L(R.fehlend) && R.fehlend.length) daten.fehlende_daten = R.fehlend;
const system = 'Du schreibst für den Bericht einer Influencer-Agentur eine kurze Einordnung der Zahlen auf Deutsch: 3 bis 5 Sätze, sachlich, genderneutral, ohne Überschrift, ohne Aufzählung, ohne Emojis, ohne Links. '
  + 'Verwende ausschließlich Zahlen und Angaben aus DATEN. Erfinde keine Werte und rechne keine neuen Werte aus (keine Summen, Durchschnitte oder Prozente, die nicht in DATEN stehen). '
  + 'Steht bei einem Wert "nicht verfügbar", schreibe das so oder lass den Punkt weg. Keine Vermutungen über Gründe, die nicht aus DATEN hervorgehen. '
  + 'Werte mit "manuell" stammen vom Talent selbst; nenne das, wenn du sie verwendest.';
const text = 'DATEN (JSON):\n' + JSON.stringify(daten).slice(0, 20000);
return [{ json: { modell: (R.ki || {}).modell || '', system, text } }];

// Bericht bauen (Stefan 18.10.2026): HTML für den PDF-Dienst (wie BERICHT 2) im Corporate Design der Agentur (CD 1).
// Alle Zahlen und Texte kommen fertig aus der Datenbank (talents_bericht_inhalt); hier wird nur angeordnet und HTML-escapt.
// "Ohne Agenturname": kein Logo, kein Name in Kopf und Fußzeile; Farben und Schrift bleiben.
// Fehler (z. B. unvollständiges Corporate Design) gehen als Feld "fehler" weiter; der Bericht wird dann als nicht erstellt gemeldet.
const R = $('Inhalt laden').first().json.r || {};
const B = R.bericht || {};
const L = Array.isArray;
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const ohneEmoji = v => String(v ?? '').replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}]/gu, '');
const wt = w => (w && typeof w === 'object' ? (w.text === undefined || w.text === null ? '–' : String(w.text)) : (w === null || w === undefined || w === '' ? '–' : String(w)));
const CD0 = $('Corporate Design (CD 1)').first().json || {};
if (CD0.error || !CD0.farben || !CD0.abgeleitet) {
  const f = CD0.error ? String(CD0.error.message || CD0.error).replace(/\s*\[line \d+\]\s*$/, '') : 'Corporate Design nicht lesbar.';
  return [{ json: { fehler: f.slice(0, 300) } }];
}
const CD = CD0;
const FIRMA = B.mit_agentur ? String(B.agentur || CD.unternehmen || '').trim() : '';
const LOGO = B.mit_agentur && CD.logos && CD.logos.logo_fuer_dunkel ? CD.logos.logo_fuer_dunkel : '';
const C = { dunkel: CD.farben.dunkel, akzent: CD.farben.akzent, akzentDunkel: CD.farben.akzentDunkel, hell: CD.farben.hell, grau: CD.farben.grau,
  linie: CD.abgeleitet.tabellenLinie, warn: CD.farben.warnung, weiss: CD.farben.textAufDunkel, nebenDunkel: CD.abgeleitet.dunkelNebentext };

// KI-Einordnung: nur wenn gewünscht; Text aus der Antwort, sonst ein fester Hinweis "nicht verfügbar"
const KI = R.ki || {};
let kiText = '', kiHinweis = '';
if (KI.gewuenscht) {
  if (KI.gesperrt) kiHinweis = KI.hinweis_gesperrt;
  else {
    let roh = '';
    try { const c = $('KI-Verbrauch buchen').first().json.content; roh = (L(c) ? c : []).filter(b => b && b.type === 'text').map(b => String(b.text || '')).join('\n'); } catch (x) { roh = ''; }
    kiText = ohneEmoji(roh).replace(/\r/g, '').replace(/[*#_`]+/g, '').trim().slice(0, 1500);
    if (!kiText) kiHinweis = KI.hinweis_fehler;
  }
}

// ---------- Bausteine ----------
const kachel = (wert, label, zusatz, cls) => '<div class="kachel"><div class="wert' + (cls ? ' ' + cls : '') + '">' + esc(wert) + '</div><div class="label">' + esc(label) + '</div>' + (zusatz ? '<div class="zusatz">' + esc(zusatz) + '</div>' : '') + '</div>';
const verText = k => k && k.veraenderung && k.veraenderung.text && k.veraenderung.text !== '–' ? k.veraenderung.text + ' zum Vorzeitraum' : '';
const tabelle = (kopf, zeilen, rechts) => '<table><thead><tr>' + kopf.map((k, i) => '<th' + (rechts.includes(i) ? ' class="r"' : '') + '>' + esc(k) + '</th>').join('') + '</tr></thead><tbody>' +
  zeilen.map(z => '<tr>' + z.map((v, i) => '<td' + (rechts.includes(i) ? ' class="r"' : '') + '>' + (v && typeof v === 'object' && v.html ? v.html : esc(v)) + '</td>').join('') + '</tr>').join('') + '</tbody></table>';
const notiz = t => t ? '<p class="notiz">' + esc(t) + '</p>' : '';
const kurzLink = u => { const s = String(u || ''); return /^https:\/\/[^\s"<>]+$/.test(s) ? { html: '<a href="' + esc(s) + '">' + esc(s.replace(/^https:\/\/(www\.)?/, '').slice(0, 38)) + '</a>' } : '–'; };

// Verlauf als Balken (SVG); Tage ohne Zahlen als kurzer grauer Strich
const verlauf = v => {
  const T = L(v && v.tage) ? v.tage : [];
  const k = v && v.kennzahl;
  if (!T.length || !k) return notiz('Für diesen Zeitraum liegen keine Tageszahlen vor.');
  const w = T.map(t => (t[k] === null || t[k] === undefined || !isFinite(Number(t[k])) ? null : Number(t[k])));
  const max = Math.max(1, ...w.filter(x => x !== null));
  const BR = 600 / T.length, H = 90;
  let svg = '<svg viewBox="0 0 600 ' + (H + 16) + '" width="100%" height="34mm" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">';
  w.forEach((x, i) => {
    const xp = (i * BR + BR * 0.15).toFixed(2), bw = (BR * 0.7).toFixed(2);
    if (x === null) svg += '<rect x="' + xp + '" y="' + (H - 2) + '" width="' + bw + '" height="2" fill="' + C.linie + '"/>';
    else { const h = Math.max(1, x / max * H); svg += '<rect x="' + xp + '" y="' + (H - h).toFixed(2) + '" width="' + bw + '" height="' + h.toFixed(2) + '" fill="' + C.akzent + '"/>'; }
  });
  svg += '<line x1="0" y1="' + H + '" x2="600" y2="' + H + '" stroke="' + C.linie + '" stroke-width="1"/>';
  svg += '<text x="0" y="' + (H + 13) + '" font-size="10" fill="' + C.grau + '">' + esc(T[0].datum) + '</text><text x="600" y="' + (H + 13) + '" font-size="10" text-anchor="end" fill="' + C.grau + '">' + esc(T[T.length - 1].datum) + '</text></svg>';
  return '<div class="verlauf"><div class="verlauf-titel">' + esc(v.kennzahl_name || '') + ' je Tag (höchster Wert ' + esc(String(Math.round(max)).replace(/\B(?=(\d{3})+(?!\d))/g, '.')) + ')</div>' + svg + '</div>';
};
const kennzahlen = d => {
  const K = L(d.kennzahlen) ? d.kennzahlen : [];
  let h = '<div class="kacheln">' + K.map(k => kachel(wt(k), k.name, k.manuell ? 'manuell' : (k.schluessel === 'follower' ? (k.zusatz || '') : verText(k)), k.manuell ? 'manuell' : '')).join('') + '</div>';
  const man = K.filter(k => k.manuell && k.quelle_text).map(k => k.name + ': ' + k.quelle_text);
  h += man.map(notiz).join('');
  h += verlauf(d.verlauf || {});
  const JK = L(d.je_kanal) ? d.je_kanal : [];
  if (JK.length > 1) h += '<h3>Je Kanal</h3>' + tabelle(['Kanal', 'Follower', 'Reichweite', 'Aufrufe', 'Interaktionen'], JK.map(k => [k.plattform_name + ' ' + k.text + (k.status_text !== 'verbunden' ? ' (' + k.status_text + ')' : ''), wt(k.follower), wt(k.reichweite), wt(k.aufrufe), wt(k.interaktionen)]), [1, 2, 3, 4]);
  h += notiz([d.vergleich_text, d.datenstand].filter(Boolean).join(' · '));
  h += (L(d.hinweise) ? d.hinweise : []).map(notiz).join('');
  return h;
};
const beitraege = d => {
  const P = L(d.beitraege) ? d.beitraege : [];
  if (!P.length) return notiz(d.hinweis || 'Keine Beiträge in diesem Zeitraum.');
  return tabelle(['Datum', 'Art', 'Konto', 'Reichweite', 'Aufrufe', 'Interaktionen', 'Rate', 'Link'],
    P.map(p => [p.erstellt || '–', p.art_name || 'Beitrag', p.konto || '', wt(p.reichweite), wt(p.aufrufe), wt(p.interaktionen), p.interaktionsrate ? p.interaktionsrate.text : '–', kurzLink(p.link)]), [3, 4, 5, 6])
    + (d.anzahl_im_zeitraum > P.length ? notiz(d.anzahl_im_zeitraum + ' Beiträge im Zeitraum, gezeigt die ' + P.length + ' mit der höchsten Reichweite (ohne Storys).') : '');
};
const beispiele = d => {
  const P = L(d.beitraege) ? d.beitraege : [];
  if (!P.length) return notiz('Keine Beiträge in den letzten 90 Tagen.');
  return '<div class="karten">' + P.map(p => '<div class="karte">' + (p.vorschau_url ? '<img src="' + esc(p.vorschau_url) + '" alt="" referrerpolicy="no-referrer" onerror="this.remove()">' : '') +
    '<div class="karte-text"><strong>' + esc(p.art_name || 'Beitrag') + '</strong> · ' + esc(p.erstellt || '') + '<br>Reichweite ' + esc(wt(p.reichweite)) + ' · Aufrufe ' + esc(wt(p.aufrufe)) + '<br>Interaktionen ' + esc(wt(p.interaktionen)) +
    (p.link ? '<br><a href="' + esc(p.link) + '">Beitrag ansehen</a>' : '') + '</div></div>').join('') + '</div>';
};
const zielgruppe = d => {
  const G = L(d.gruppen) ? d.gruppen : [];
  if (!G.length) return notiz(d.hinweis || 'Zielgruppe nicht verfügbar.');
  return '<div class="gruppen">' + G.map(g => '<div class="gruppe"><div class="gruppe-titel">' + esc(g.name) + (g.plattform_name ? ' · ' + esc(g.plattform_name) : '') + '</div>' +
    (L(g.eintraege) ? g.eintraege : []).slice(0, 8).map(e => { const a = Math.max(0, Math.min(100, Number(e.anteil) || 0));
      return '<div class="zeile"><span class="name">' + esc(e.name) + '</span><span class="balken"><span style="width:' + a.toFixed(1) + '%"></span></span><span class="r">' + esc(e.anteil_text || e.text) + '</span></div>'; }).join('') +
    '<div class="stand">Stand ' + esc(g.stand || '–') + (g.manuell ? ' · manuell (' + esc(g.quelle_text || '') + ')' : '') + '</div></div>').join('') + '</div>';
};
const formate = d => {
  const F = L(d.formate) ? d.formate : [];
  if (!F.length) return notiz(d.hinweis || 'Keine Beiträge in diesem Zeitraum.');
  return tabelle(['Beitragsart', 'Anzahl', 'Reichweite (Schnitt)', 'Aufrufe (Schnitt)', 'Interaktionen (Schnitt)', 'Interaktionsrate'],
    F.map(f => [f.name, String(f.anzahl), wt(f.schnitt_reichweite), wt(f.schnitt_aufrufe), wt(f.schnitt_interaktionen), wt(f.interaktionsrate)]), [1, 2, 3, 4, 5]) + notiz(d.notiz);
};
const manuell = d => {
  const W = L(d.werte) ? d.werte : [];
  if (!W.length) return notiz(d.hinweis || 'Keine Zahlen ohne Verbindung für diesen Zeitraum.');
  return tabelle(['Plattform', 'Kennzahl', 'Wert', 'Zeitraum', 'Quelle'], W.map(w => [w.plattform_name + (w.konto ? ' ' + w.konto : ''), w.kennzahl_name + (w.beitrag ? ' (' + w.beitrag + ')' : ''), w.text || '–', w.zeitraum_text, w.quelle_text]), [2])
    + notiz('Diese Zahlen hat das Talent selbst geliefert; sie wurden von der Agentur geprüft und bestätigt.') + notiz(d.hinweis && W.length ? d.hinweis : '');
};
const profil = d => {
  const K = L(d.kanaele) ? d.kanaele : [];
  return '<div class="profil"><div class="profil-name">' + esc(d.anzeigename || '') + '</div>' + (d.kuenstlername && d.name && d.kuenstlername !== d.name ? '<div class="profil-unter">' + esc(d.name) + '</div>' : '') +
    (K.length ? '<div class="profil-kanaele">' + K.map(k => esc(k.plattform_name + ' ' + k.text) + (k.follower && k.follower.wert !== null ? ' · ' + esc(wt(k.follower)) + ' Follower' : '')).join('<br>') + '</div>' : '') + '</div>' +
    '<div class="kacheln">' + kachel(wt(d.follower), 'Follower', d.follower_manuell ? 'manuell' : '', d.follower_manuell ? 'manuell' : '') + kachel(wt(d.reichweite), 'Reichweite (28 Tage)') +
    kachel(wt(d.interaktionsrate), 'Interaktionsrate') + kachel(String(d.beitraege ?? '–'), 'Beiträge (28 Tage)') + '</div>' + notiz([d.zeitraum_text, d.stand].filter(Boolean).join(' · '));
};
const vergleich = d => {
  const Z = L(d.zeilen) ? d.zeilen : [];
  if (!Z.length) return notiz(d.hinweis || 'Keine Zahlen.');
  return tabelle(['Talent', 'Follower', 'Reichweite', 'Veränderung', 'Aufrufe', 'Interaktionen', 'Rate', 'Beiträge'],
    Z.map(z => [z.anzeigename, wt(z.follower), wt(z.reichweite), z.reichweite && z.reichweite.veraenderung ? z.reichweite.veraenderung.text : '–', wt(z.aufrufe), wt(z.interaktionen), wt(z.interaktionsrate), String(z.beitraege ?? '–')]),
    [1, 2, 3, 4, 5, 6, 7]) + notiz(d.hinweis) + notiz('Veränderung: Reichweite je Tag im Vergleich zum gleich langen Zeitraum davor.');
};
const kampagne = d => {
  const K = d.kampagne || {}, G = d.gesamt || {}, T = L(d.talents) ? d.talents : [];
  let h = '<p class="unterkopf">' + esc([K.marke, K.name, K.zeitraum_text].filter(Boolean).join(' · ')) + '</p>';
  h += '<div class="kacheln">' + kachel(wt(G.reichweite), 'Reichweite gesamt') + kachel(wt(G.aufrufe), 'Aufrufe gesamt') + kachel(wt(G.interaktionen), 'Interaktionen gesamt') +
    kachel(wt(G.beitraege), 'Beiträge') + '</div>';
  if (T.length) h += '<h3>Je Talent</h3>' + tabelle(['Talent', 'Beiträge', 'Reichweite', 'Aufrufe', 'Interaktionen'],
    T.map(x => [x.anzeigename || '', L(x.beitraege) ? String(x.beitraege.length) : wt(x.beitraege), wt(x.reichweite), wt(x.aufrufe), wt(x.interaktionen)]), [1, 2, 3, 4]);
  const P = [];
  T.forEach(x => (L(x.beitraege) ? x.beitraege : []).forEach(p => P.push(Object.assign({ talent: x.anzeigename }, p))));
  if (P.length) h += '<h3>Beiträge</h3>' + tabelle(['Talent', 'Datum', 'Art', 'Reichweite', 'Aufrufe', 'Interaktionen', 'Link'],
    P.slice(0, 40).map(p => [p.talent || '', p.erstellt || '–', p.art_name || 'Beitrag', wt(p.reichweite), wt(p.aufrufe), wt(p.interaktionen), kurzLink(p.link)]), [3, 4, 5]) +
    (P.length > 40 ? notiz('Gezeigt werden 40 von ' + P.length + ' Beiträgen.') : '');
  h += (L(d.hinweise) ? d.hinweise : []).map(notiz).join('');
  return h;
};
const BAU = { kennzahlen, beitraege, beispiele, zielgruppe, formate, manuell, profil, vergleich, kampagne };

let inhalt = '';
const viele = (R.talents || []).length > 1;
for (const b of (L(R.bausteine) ? R.bausteine : [])) {
