// PDF erstellen (Stefan 18.10.2026): wie BERICHT 2 über den internen Render-Dienst ally-render (Gotenberg), mit Fußzeile (Seitenzahlen).
// Wirft keinen Fehler: ohne PDF geht "fehler" weiter, damit der Bericht als "nicht erstellt" gemeldet wird.
const j = $input.first().json || {};
if (j.fehler) return [{ json: { fehler: j.fehler } }];
const RENDER = 'http://ally-render:3000';
const ascii = x => { let o = ''; for (const ch of x) { const c = ch.codePointAt(0); o += c < 128 ? ch : '&#' + c + ';'; } return o; };
const grenze = '----ally' + Date.now().toString(16) + Math.random().toString(16).slice(2);
const felder = { preferCssPageSize: 'true', printBackground: 'true', marginTop: '0', marginBottom: '0', marginLeft: '0', marginRight: '0', waitForExpression: 'window.fertig === true', waitDelay: '0.3s' };
let body = '';
for (const [k, v] of Object.entries(felder)) body += '--' + grenze + '\r\nContent-Disposition: form-data; name="' + k + '"\r\n\r\n' + v + '\r\n';
const datei = (name, html) => '--' + grenze + '\r\nContent-Disposition: form-data; name="files"; filename="' + name + '"\r\nContent-Type: text/html\r\n\r\n' + ascii(html) + '\r\n';
body += datei('index.html', j.pdf_html) + datei('footer.html', j.fuss_html) + '--' + grenze + '--\r\n';
let antwort;
try {
  antwort = await this.helpers.httpRequest({ method: 'POST', url: RENDER + '/forms/chromium/convert/html', body, headers: { 'Content-Type': 'multipart/form-data; boundary=' + grenze },
    encoding: 'arraybuffer', json: false, timeout: 120000, returnFullResponse: true, ignoreHttpStatusErrors: true });
} catch (e) {
  return [{ json: { fehler: 'PDF konnte nicht erstellt werden (Render-Dienst nicht erreichbar).' } }];
}
if (antwort.statusCode !== 200) return [{ json: { fehler: 'PDF konnte nicht erstellt werden (Render-Dienst ' + antwort.statusCode + ').' } }];
const buf = Buffer.from(antwort.body);
const bin = await this.helpers.prepareBinaryData(buf, j.datei, 'application/pdf');
return [{ json: { aktion: 'ablegen', bereich: 'ally', pfad: j.pfad, ueberschreiben: false, groesse: buf.length }, binary: { datei: bin } }];
